INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('46cd37e8-7c7a-4841-96bd-758d485ebc17', 'Incremento de Renta', '5', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months.\n- For the first 5 years of the Lease Term, the increase is capped at 7%.\n- The increase is based on the change in the National Consumer Price Index (INPC).\n- The INPC is published monthly by the National Institute of Statistics and Geography (INEGI).\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and two months before the new adjustment.\n- If the INPC increase is more than 7% annually, the maximum increase will still be 7% for the first 5 years.\n- After 5 years or in case of an extension, the increase will match the INPC percentage.', 'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, topado durante los primeros 5 (cinco) años del Plazo del Arrendamiento al 7% (siete por ciento) bajo los términos y condiciones señalados en la cláusula Quinta, contado a partir de la fecha de inicio de pago de renta, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 7% (siete por ciento) anual éste será el porcentaje máximo de incremento de la Renta Mensual durante los primero 5 (cinco) años del Plazo del Arrendamiento, por lo que en caso de cualquier prórroga, el porcentaje de incremento será igual al del INPC.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('46cd37e8-7c7a-4841-96bd-758d485ebc17', 'Common Area Maintenance Charges', '8', '9', 'A) GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The administration and maintenance costs are included in the monthly rent.\n- In cases of unforeseen events or force majeure, the landlord is not responsible for any damage or issues related to the quality, quantity, failure, unavailability, discontinuity, or interruption of services covered by the maintenance fee or the shopping center.\n- Such issues will not:\n  - Be a reason to terminate the contract.\n  - Be considered a hidden defect or construction fault by the landlord.\n  - Give the tenant the right to withhold or reduce the monthly rent or fail to meet any other contractual obligations.', E'Los Gastos de Administración y Mantenimiento se encuentra incluido en la Renta Mensual.\n\nEn caso fortuito y/o de fuerza mayor, la Arrendadora no será responsable ante la Arrendataria por cualquier daño o perjuicio derivado de la calidad, cantidad, falla, falta de disponibilidad, discontinuidad o interrupción en el suministro de cualquier servicio derivado de la cuota de mantenimiento y/o del Centro Comercial y dichas anomalías no serán: (i) causa de terminación de éste contrato; (ii) consideradas un vicio oculto o defecto de construcción a cargo de la Arrendadora; o (iii) un derecho, motivo o facultad de la Arrendataria para retener o reducir la Renta Mensual o incumplir cualquier otra obligación a su cargo derivada de éste Contrato.');
