INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('70e92e1d-0dbe-46c6-95cd-33a81c8ac537', 'Fecha de Apertura', '16 de marzo de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('70e92e1d-0dbe-46c6-95cd-33a81c8ac537', 'Late Fees', '3', '4', 'CONTRAPRESTACIÓN', E'- If the subtenant does not pay the rent within the first ten days of the month, late fees will start to accumulate from the eleventh day.\n- The late fees are calculated at a rate of 4% per month, spread out over the time the payment is late.\n- If there are any outstanding rent or interest payments, any payment made by the subtenant will first cover the interest, and any remaining amount will go towards the overdue rent.', 'En caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('70e92e1d-0dbe-46c6-95cd-33a81c8ac537', 'Incremento de Renta', '4', '6', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase annually in January.\n- The first increase will be in January 2023.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index for measuring inflation in Mexico.\n- Annual increases cannot exceed 8% of the current payment amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2023, en la misma proporción en que aumente el Índice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho período.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('70e92e1d-0dbe-46c6-95cd-33a81c8ac537', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include any applicable value-added tax (VAT) or any future tax that replaces it.\n- The subtenant will not contribute to the shopping center''s advertising expenses, so no advertising costs will be charged to them.', 'EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. Las Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste.');
