,"grid_full_address":"50 Avenida Carlos Hank Gonzalez, PA-02, Valle De Anahuac, Ecatepec De Morelos, Estado de México 55210","map_addr_1":"50 Avenida Carlos Hank Gonzalez","map_addr_2":"PA-02","map_city_state_zip":"Valle De Anahuac, Ecatepec De Morelos, Estado de México 55210","grid_brand":"Planet Fitness","location_created_at":"2025-09-22 17:42:00","active_lease_count_over_time":50598,"location_count_over_time":57479,"remaining_rent_liability_over_time":50598}'::jsonb);
