INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('d8cc5bbe-e99d-479c-8383-7341772b6d8b', 'Fecha de Apertura', '9 de noviembre de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('d8cc5bbe-e99d-479c-8383-7341772b6d8b', 'Late Fees', '14', '16', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total de la deuda no pagada a tiempo.\n- Se cobra si el pago se retrasa más de 45 días desde la fecha de vencimiento.\n- El interés se calcula cada mes o parte de un mes mientras dure el retraso.\n- Se aplica desde la fecha en que debía hacerse el pago hasta que se pague.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('d8cc5bbe-e99d-479c-8383-7341772b6d8b', 'Incremento de Renta', '4', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months starting from the store''s opening date (September 11, 2024).\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and the INPC two months before the new adjustment.\n- If the increase percentage is more than 4%, the maximum increase will be capped at 4%.', 'Las Partes convienen que la Renta Mensual será incrementada cada 12 meses, contado a partir de la fecha de apertura del local (11 de septiembre de 2024), se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 4% (cuatro por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('d8cc5bbe-e99d-479c-8383-7341772b6d8b', 'Common Area Maintenance Charges', '8', '9', 'PAGO DE OTROS CONCEPTOS', 'No applicable information provided.', 'No aplica');
